export default async function(app){const old=app.layers[app.config.layerId];await old.load();const next=old.clone();next.id=old.id;next.purgeOptions={maxObservations:100,displayCount:10000};const icon=(plow,color)=>({type:'picture-marker',width:34,height:34,url:'data:image/svg+xml;base64,'+btoa(`<svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 64 64"><circle cx="32" cy="32" r="30" fill="white" stroke="${color}" stroke-width="3"/><g stroke="#172b3a" stroke-width="2"><path d="${plow?'M10 24H32V40H10ZM32 28H43L49 35V40H32Z':'M10 32H27V24H39L48 33V40H10Z'}" fill="${color}"/><path d="M33 28H39L44 33H33Z" fill="#dff4ff"/>${plow?'<path d="M49 36L57 32V45L49 42Z" fill="#f3b941"/>':''}<circle cx="20" cy="42" r="5" fill="#253442"/><circle cx="41" cy="42" r="5" fill="#253442"/></g></svg>`)});const renderer={type:'unique-value',field:'vehicletype',defaultSymbol:icon(false,'#687787'),uniqueValueInfos:[{value:'Snow Plow',label:'Snow plow',symbol:icon(true,'#dc7900')},{value:'Pickup',label:'Pickup',symbol:icon(false,'#1876bc')}]};next.renderer=renderer;next.trackInfo={enabled:true,timeField:'startTimeField',maxDisplayObservationsPerTrack:100,latestObservations:{visible:true,renderer,labelingInfo:[{labelExpressionInfo:{expression:'$feature.vehiclename'},labelPlacement:'above-center',symbol:{type:'text',color:'#203547',haloColor:'white',haloSize:1.5,font:{size:9}}}]},previousObservations:{visible:true,renderer:{type:'simple',symbol:{type:'simple-marker',size:4,color:'#43b5d8',outline:{color:'white',width:0.5}}}},trackLines:{visible:true,renderer:{type:'simple',symbol:{type:'simple-line',color:[85,178,210,0.8],width:2}}}};const parent=old.parent,index=parent.layers.indexOf(old);parent.remove(old);parent.add(next,index);app.onCleanup(()=>{parent.remove(next);if(!parent.layers.includes(old))parent.add(old,index);next.destroy();});await next.load();await app.view.whenLayerView(next);}